import type { ToolDef } from "../core/types.js";
import { categoryTool } from "../surface/category-tool.js";
import { actions as epicActions, schema as epicSchema } from "./epic/level.generated.js";
import { specBp, schema as specSchema } from "./specs/level.generated.js";
import { specBp as editorSpecBp, schema as editorSpecSchema } from "./specs/editor.generated.js";
import { borrowSchema } from "../surface/handler-spec.js";

export const levelTool: ToolDef = categoryTool(
  "level",
  "Level actors, selection, components, level management, volumes, lights, and splines.",
  {
    get_outliner:       specBp("read", "List actors (each row includes editorHidden - hidden in the viewport but still rendering in game, and folderPath). classFilter is a case-sensitive SUBSTRING over the class name by default; pass exactClass=true to require the exact class instead. folderPath matches one World Outliner folder exactly and folderPathPrefix matches that folder and everything nested under it, so narrowing a folder to a single class no longer needs a get_actor_details round trip per entry (#911) (#717).", "get_world_outliner"),
    set_editor_visibility: specBp("mutate", "Bulk set editor-only visibility (temporarily-hidden-in-editor) on actors. Targets actorLabels[] or all=true (#717).", "set_editor_visibility"),
    place_actor:        specBp("mutate", "Spawn actor. Pass world:pie to spawn into the running PIE world (#585).", "place_actor"),
    delete_actor:       specBp("mutate", "Remove actor. A label matching several actors is refused with the candidates rather than deleting one of them (#983).", "delete_actor"),
    // lint-prose-allow: tier  RecastNavMesh's own name for its three generation tiers
    get_actor_details:  specBp("read", "Inspect actor. With includeProperties=true, a UPROPERTY declared as a C-style FIXED ARRAY (int32 Foo[3], one FProperty with ArrayDim 3) comes back as a JSON ARRAY of its elements plus arrayDim, instead of element 0 presented as the whole value. That mattered on RecastNavMesh NavMeshResolutionParams, whose three entries are the Low, Default and High generation tiers, and where reporting only Low sent a user tuning cell sizes against numbers the engine was not using (#927). Containers over 64 entries and values over 16384 characters are cut and marked truncated, with count for a container (#1277).", "get_actor_details"),
    move_actor:         specBp("mutate", "Transform actor. In the editor world the move is one undo transaction and dirties the actor's package, reported as packageDirty, so level(save) persists it (#1261), and it ends with PostEditMove(true) so OnActorMoved listeners such as PCG see it (#1315). Pass world:pie to move a live PIE actor (resolves labels/names from get_outliner {world:pie}) (#586).", "move_actor"),
    aim_actor_at:       specBp("mutate", "Rotate an actor so its forward (+X) points at a target (#566/#983). In the editor world the aim is one undo transaction and dirties the actor's package, reported as packageDirty, so level(save) persists it.", "aim_actor_at"),
    nav_project_point:  specBp("read", "Project a world point onto the navmesh. Returns onNavMesh + projectedLocation (#585).", "nav_project_point"),
    select:             specBp("mutate", "Select actors. A label naming several actors selects all of them; selectedPaths reports exactly which (#983). The level editor never selects a child actor of a ChildActorComponent itself, so naming one selects the actor that owns it and lists the substitution under redirected (#1656).", "select_actors"),
    select_component:   specBp("mutate", "Select one component in the level editor, with its owning actor, replacing the selection unless addToSelection=true. componentName is looked up on the actor, then on its child actors. A component on a child actor cannot be selected in the level editor, so the ChildActorComponent that spawned it is selected instead, as a viewport click would do, and the result says so with redirected=true. Returns selectedActorPath and selectedComponent, and unchanged=true when that was already the selection (#1656).", "select_component"),
    get_selected:       specBp("read", "Get selection.", "get_selected_actors"),
    add_component:      specBp("mutate", "Add component to actor.", "add_component_to_actor"),
    remove_component:   specBp("mutate", "Remove instance component from a level actor by name. Idempotent: returns alreadyDeleted=true if no matching component exists (#426).", "remove_component_from_actor"),
    set_component_property: specBp("mutate", "Set component prop. A C-style FIXED ARRAY element is addressed by index in the dotted path ('Foo[2].Bar'); without an index every write lands on element 0 (#927). Pass value=null to clear a TObjectPtr/SoftObject/WeakObject/UClass/Interface reference (#420). Resolves inherited/SCS components on placed Blueprint instances case-insensitively, and refreshes the scene transform after RelativeLocation/RelativeRotation/RelativeScale3D writes (#539). Pass world='pie' (with optional pieInstance) to write to a LIVE PIE component rather than the editor one (#763). StaticMesh on a static mesh component goes through SetStaticMesh, so the bounds and render state follow the new mesh and it draws; the result reports previousValue, value and changed (#1548).", "set_component_property"),
    nudge_component: specBp("mutate", "Adjust an exact named SceneComponent using frame-relative translation, quaternion rotation, or uniform relative scale. frame=parent uses the parent COMPONENT transform; the socket is reported separately. axisRotation and viewRotation are mutually exclusive. An editor-world apply ends with PostEditMove(true) on the owner, so OnActorMoved listeners see it (#1315). viewRotation is observer-relative to the selected frame, not a player camera: clockwise/counterclockwise is resolved using Unreal screen basis and returned as signed degrees. dryRun=false by default; dryRun returns current spatial inspection plus requested world location/rotation and relative scale without a transaction, modification, setter, dirtiness, or rollback. The rollback it emits is a level(restore_component_transform) call.", "nudge_component"),
    restore_component_transform: { ...specBp("mutate", "Put an exact named SceneComponent back to a relative transform: the relativeTransform nudge_component records in its rollback, so a nudge can be undone by hand as well as by the flow runner. The quaternion is what is applied. A component already at that transform is reported unchanged.", "restore_component_relative_transform"), destructive: false },
    get_component_details: specBp("read", "Read a placed actor's component transforms. With componentName returns that component's relative+world location/rotation/scale, class, and attach parent; without it lists every component. With includeValues=true also dumps arbitrary UPROPERTY values (custom fields, CharacterMovement MaxWalkSpeed, etc.); world='pie' reads the live PIE instance (#539/#584).", "get_component_details"),
    get_current:        specBp("read", "Get current level name and path.", "get_current_level"),
    load:               specBp("mutate", "Open level or load map: switch the editor to another map as the current editor level (the native load_map). Returns levelPath, levelName, worldPath and previousLevelPath, and refuses a path that does not exist. Refuses while the open map or its external actor packages have unsaved changes, naming them in dirtyPackages: pass saveFirst=true to save them first or discardUnsaved=true to drop them (a never-saved Untitled map included, which has no file to save to), and the result lists savedPackages or discardedPackages (#1259).", "load_level"),
    clear_level_script: specBp("mutate", "Preview or remove every node and member variable from the currently loaded persistent level's Level Blueprint. Defaults to dryRun=true. Actors are untouched; save=true saves only the current level after a successful compile.", "clear_level_script"),
    save:               specBp("mutate", "Save the level currently being edited, and say what happened to each package. Takes the same package path editor(save_dirty) uses, so the two can no longer disagree about whether one package was written: the old action returned a bare {success:false, error:'Failed to save current level'} on a map that save_dirty then wrote seconds later, and a false failure makes an agent redo work that was already on disk (#964). On a World Partition or one-file-per-actor map the actors live in their own packages, so those are saved too and each is reported separately. A package that was already clean is reported as skipped, not as a failure. The emptied external package of a deleted World Partition or one-file-per-actor actor is deleted from disk, as the editor's own save does, and listed under deleted (#1301). The bridge keeps that package loaded from the delete until a save commits it, so a garbage collection in between no longer loses the delete (#1545). On failure the error names the package, the resolved file, whether that file exists and is read-only, the engine's ESavePackageResult and the error/warning lines the save itself emitted. Saving during PIE is refused by name rather than failing silently. With commitDeletes=true it goes through the editor's own dirty-package save instead, which deletes the external package of a deleted World Partition actor (a direct save fails on it with 'SavePackage returned false') and saves every other dirty map and content package, reporting written, deleted and stillDirty per package (#1156).", "save_level"),
    list:               specBp("read", "List levels: the persistent level first, then every streaming level with its loaded and visible state, in the world's own streaming order.", "list_levels"),
    create:             editorSpecBp("mutate", "Create a new level at a path and open it. levelPath is validated before the engine is asked: an omitted or malformed path is refused outright, because NewLevel(\"\") logs an engine error and lands the editor on an untitled map that cannot then be saved (#833). worldPartition=true makes a blank World Partition level with one file per actor, and the result reports worldPartition and externalActors (#1247). A level made from a World Partition templateLevel is saved and reopened before returning (savedAndReopened), so its actor descriptors point at the new map rather than the /Temp world it was built in (#1284).", "create_new_level"),
    spawn_volume:       specBp("mutate", "Place volume.", "spawn_volume"),
    list_volumes:       specBp("read", "List volumes, sorted by actor path so a page boundary is stable.", "list_volumes"),
    set_volume_properties: specBp("mutate", "Edit volume.", "set_volume_properties"),
    spawn_light:        specBp("mutate", "Place light (#331/#310).", "spawn_light"),
    set_light_properties: specBp("mutate", "Edit a light OR SkyLight (intensity/color now work on SkyLight too, #608).", "set_light_properties"),
    set_fog_properties: specBp("mutate", "Edit ExponentialHeightFog incl. volumetric fog (#608).", "set_fog_properties"),
    get_actors_by_class: specBp("read", "List actors by class. Matches Blueprint subclasses of a native base via IsChildOf when className resolves to a UClass (short name, /Script path, or BP class path), else falls back to name-substring. Each actor includes location/rotation/scale, live when world=pie. labelPrefix narrows to actors whose editor label starts with it (case-sensitive), and with it className may be omitted to match every class (#1113) (#675).", "get_actors_by_class"),
    get_actors_by_component_class: specBp("read", "List actors that own a component of a given class (exact or substring match). Returns each actor plus its matchedComponents. For a whole-map question use level(query_components), which filters and counts in the editor instead of returning every candidate (#582).", "get_actors_by_component_class"),
    query_components: {
      ...specBp("read", "Ask one level-wide question about components and get the answer, not the candidates. Selection, projection, predicates, grouping and counts all evaluate in the editor, so a 4,000 actor map costs one call instead of thousands. Computed (not raw) values: shadow.effectiveCastShadow crosses CastShadow with visibility, bHiddenInGame, owner hidden and bCastHiddenShadow, so a hidden debug marker with CastShadow=true is correctly NOT a shadow caster; every mobility and collision enum comes back as a clean name (Movable, QueryAndPhysics), never as EComponentMobility.MOVABLE; navigation.effectiveNavRelevant crosses bCanEverAffectNavigation with collision and custom navigable geometry. Never writes, and reports dirtiedPackages so you can see that. Field groups for 'fields' and for dot paths: transform, bounds, localBounds (unscaled, includes UBoxComponent BoxExtent), shadow, nanite, navigation, tick (tick settings plus componentActive and autoActivate, the transient active state no property read reaches, #1656), materials (per slot: effective path, componentOverride vs meshDefault, slot name/index, isNull, isWorldGrid, materialClass and isDynamic to tell a MaterialInstanceConstant from a MaterialInstanceDynamic, #1303), mesh (adds instanceCount + hierarchical for an ISM/HISM, #986), decal, health (roll-up incl. suspect), attachment (parentComponent, parentActor, socket, relative transform, isRoot, onlyOwnerSee/ownerNoSee and firstPersonPrimitiveType where the engine has it; with world=pie this enumerates a live pawn's components for dual-mesh visibility checks, #1250), customPrimitiveData (runtime: the values SetCustomPrimitiveData* wrote, e.g. from a construction script, and defaults: the serialized array, #1303), physics (simulatingPhysics, gravityEnabled, awake, linearVelocity, angularVelocityDegrees, mass while simulating, physMaterialOverride and the effective physicalMaterial with friction/restitution/density; pass world=pie for live rigid bodies, #1212). A dot path used in where/groupBy/countBy turns its own group on. actorPropertyNames projects the owning actor's properties, Blueprint variables included and dotted paths allowed, under actorProps.* so per-instance BP state can be filtered, grouped and counted with the rest of the row (#1303). Child actors spawned by a ChildActorComponent are scanned like any actor, and their rows carry parentActorLabel, parentActorPath and childActorComponent; includeChildActors=true applies the actor filters (actorClass, labels, tag, folder) to the top-level owning actor instead, so actorLabelContains naming a placed actor also returns the components of its child actors (#1656). propertyNames takes the same dotted paths into the component (AttachEndTo.ComponentProperty, Items[2].Mesh). A name that resolves to nothing is listed with its reason under missingProps / missingActorProps rather than dropped, and a where/groupBy/countBy path props.X or actorProps.X projects X by itself. For one row per actor (a per-instance audit with its attach parent), add where attachment.isRoot isTrue and fields attachment: that row's attachment.parentActor and socket are the actor's own attachment (#1530). groupBy and countBy COUNT COMPONENTS, not instances: one HISM holding 5,000 instances counts as 1, so for per-mesh placement totals use level(summarize_static_mesh_usage), which sums instances and counts distinct actors. duplicateTransformTolerance reports duplicateTransformGroups. levelPath temporarily opens another map: it refuses if anything is dirty and restores the map that was open (#910/#943/#912). includeCollision adds collisionEnabled and objectType plus responseOnChannel for collisionChannel, or non-Block responses capped at 32.", "query_components"),
      timeoutMs: 300_000,
    },
    count_actors_by_class: specBp("read", "Histogram of actor classes in the level (sorted desc) (#146).", "count_actors_by_class"),
    get_runtime_virtual_texture_summary: specBp("read", "List RuntimeVirtualTextureVolume actors + their bound VirtualTexture assets (#150).", "get_runtime_virtual_texture_summary"),
    set_water_body_property: specBp("mutate", "Set a property on an actor's WaterBodyComponent (ShapeDilation, WaterLevel, etc.). Requires Water plugin. For spline edits use level(set_spline_points) (#151). A deprecated property (TessellatedWaterMeshExtent in 5.8) is not serialized: the write comes back with a warning, and TessellatedWaterMeshExtent, which is not on the body at all, is refused with the supported route, level(rebuild_water_zone) (#1156).", "set_water_body_property"),
    build_lighting:     editorSpecBp("mutate", "Build lights.", "build_lighting"),
    rebuild_water_zone: specBp("mutate", "Rebuild a WaterZone's water mesh and water info, repeating until the WaterMesh QuadTreeResolution stops changing. The grid is sized from the extent seen on the previous rebuild, so a single rebuild after a ZoneExtent or TileSize change reports a stale grid. Optionally sets zoneExtent and/or the WaterMesh tileSize first, which is the supported replacement for the deprecated TessellatedWaterMeshExtent. Returns zoneExtent, tileSize, quadTreeResolution, passes and stable per zone. Without actorLabel/actorPath every zone in the world is rebuilt. Requires Water plugin (#1156).", "rebuild_water_zone"),
    get_water_state:    specBp("read", "One structured read of every WaterZone and WaterBody. Zones: ZoneExtent, RenderTargetResolution, OverlapPriority, local tessellation settings, OwnedWaterBodies, and waterMesh TileSize, QuadTreeResolution, TessellationFactor, LODScale and the far-distance mesh settings. Bodies: OceanExtents, CollisionExtents, WaterZoneOverride, OwningWaterZone, bAffectsLandscape, ShapeDilation and every water material. Properties absent on the running engine are omitted, and deprecated fields such as TessellatedWaterMeshExtent are flagged under deprecatedProperties. Requires Water plugin (#1156).", "get_water_state"),
    get_spline_info:    specBp("read", "Read a spline component's points, closedLoop, length, and per-point tangents/types, and splineHasBeenEdited (whether a construction script rerun keeps the points). Works in editor or PIE (#553). componentName picks a specific (custom) spline; projectPoint returns the closest location, inputKey, distanceAlongSpline, distanceToSpline, and tangent (#555).", "get_spline_info"),
    set_spline_points:  specBp("mutate", "Set spline points. A point is either a bare {x,y,z} or the typed form, which keeps what a position alone loses: pointType, arriveTangent, leaveTangent, rotation and scale. The whole batch is validated before any existing geometry is cleared, so a malformed request leaves the spline as it was, and the edit goes through an editor transaction so Undo reaches it. componentName picks one spline on an actor carrying several (#1029). markEdited (default true) sets bSplineHasBeenEdited, the flag the spline editor sets, so a Blueprint construction script rerun keeps these points instead of resetting the spline to its defaults; the result reports splineHasBeenEdited, previousSplineHasBeenEdited and creationMethod, and the rollback restores the flag.", "set_spline_points"),
    create_spline_actor: specBp("mutate", "Spawn an actor whose root is a SplineComponent named Spline through splinePoints (at least two {x,y,z}, world space unless coordinateSpace is local), with closedLoop, one pointType for every point, and tags. label makes it idempotent: an existing label is reported (onConflict skip), refused (error), or has its points rewritten (update, rolled back to the previous points). A new actor rolls back through delete_actor. The spline is marked edited, so the points survive a construction script rerun.", "create_spline_actor"),
    build_spline_meshes: specBp("mutate", "Fill a spline with a chain of SplineMeshComponents from one staticMesh, for roads, fences, pipes and cables. Each piece is spacing long (default the mesh length along forwardAxis times scale), stretched so a whole number of pieces fills the spline unless stretchToFit is false; scale's other two axes set the cross-section, roll turns every piece, startOffset and endOffset leave the ends empty, collisionProfile sets collision. Output is tagged with generatorName (default SplineMeshes) and the parameters are stored on the actor, so running it again replaces the previous pieces rather than adding to them, and rebuild=true reruns the stored parameters with any passed ones on top. Rolls back to the previous run, or through clear_spline_generated when there was none.", "build_spline_meshes"),
    scatter_along_spline: specBp("mutate", "Place one or more meshes along a spline every interval centimetres (default 200) or count times, picking among meshes by weights. offset and positionJitter are in the spline's frame (x along it, y to its right, z up), yawJitter and scaleMin/scaleMax randomise rotation and uniform scale, alignToSpline (default true) turns each placement to the spline, and seed makes the result repeatable. mode instances (default) adds one HierarchicalInstancedStaticMeshComponent per mesh to the spline's actor; mode actors spawns StaticMeshActors. Output is tagged with generatorName (default SplineScatter) and a rerun replaces it; rebuild=true reuses the stored parameters. Rolls back like build_spline_meshes.", "scatter_along_spline"),
    clear_spline_generated: specBp("mutate", "Remove everything a spline generator made (its tagged components on the actor and its tagged actors) and the parameters it stored. Idempotent: nothing to remove reports alreadyDeleted. Rolls back by running the generator again with the stored parameters.", "clear_spline_generated"),
    create_blockout: specBp("mutate", "Place a blockout primitive: shape box, ramp (rises toward the actor's +X), wedge (a gable with its ridge along Y), cylinder (sides) or stairs (steps, climbing toward +X), size centimetres along the actor's axes with location at the bottom centre. It is a StaticMeshActor tagged with tag (default Blockout) and BlockoutShape:<shape>, using a unit shape mesh generated once and saved under meshFolder (default /Game/Blockout/Meshes) with the engine grid material unless material is given. Rolls back through delete_actor; the shape mesh stays for reuse.", "create_blockout"),
    list_blockout: specBp("read", "List the blockout actors carrying tag (default Blockout): label, path, shape, mesh, transform, size along the actor's own axes, bottomCentre, world bounds and tags, plus a count per shape. includeReplaced adds the actors replace_blockout put in their place, with the record restore_blockout reads.", "list_blockout"),
    match_asset_to_blockout: specBp("read", "Rank the StaticMeshes under candidateFolder by how well their bounds fit a blockout actor (actorLabel or actorPath) or every blockout carrying tag. Each candidate reports score (the mean of sizeScore and shapeScore, 1 is identical), its size, the yawOffset that fits best when allowRotation tries a quarter turn, and the uniformScale and stretchScale a fit would apply. limit caps the candidates per blockout; maxCandidates caps how many meshes are loaded.", "match_asset_to_blockout"),
    replace_blockout: specBp("mutate", "Swap blockout actors for a StaticMesh fitted to each one's bounds: assetPath for all of them, or the best match under candidateFolder for each. fit uniform (default) scales evenly to fit inside, stretch matches every axis, none keeps scale 1; the asset's bottom centre lands on the blockout's, with its rotation plus yawOffset. The replacement keeps the label and folder and carries BlockoutReplacement and a record of the blockout, and the blockout is removed. Every target is planned before anything is destroyed. Rolls back through restore_blockout.", "replace_blockout"),
    restore_blockout: specBp("mutate", "Put back the blockout a replace_blockout replacement recorded (mesh, transform, material, tags, label, folder) and remove the replacement. Takes the replacement by actorLabel, actorPath, or actorPaths as replace_blockout returns them. Rolls back through replace_blockout when every swap used the same asset, fit and yaw.", "restore_blockout"),
    set_actor_material: specBp("mutate", "Set material on actor.", "set_actor_material"),
    get_world_settings: specBp("read", "Read world settings (GameMode, KillZ, gravity, etc.).", "get_world_settings"),
    set_world_settings: specBp("mutate", "Set world settings.", "set_world_settings"),
    get_actor_bounds:   specBp("read", "Get actor AABB. Returns origin + extent (#188).", "get_actor_bounds"),
    get_component_tree: specBp("read", "Deep component-tree dump for an actor. Returns per-component: name, class, attachParent, attachSocket, mobility, visibility, relative+world transforms, tags. For PrimitiveComponents adds collisionProfile/collisionEnabled/bounds/castShadow. For StaticMeshComponent adds staticMesh + materials[], and for an ISM/HISM also instanceCount plus instanced{hierarchical,numCustomDataFloats} - the number you need before deciding whether to touch an ISM at all, since a component holding three instances and one holding three hundred thousand were otherwise the same row (#986). For SkeletalMeshComponent adds skeletalMesh + skeleton + materials[]. For NiagaraComponent adds niagara{asset,active,visible} and for AudioComponent audio{sound,playing} - runtime FX state in PIE (#581). With includeProperties, a TArray/TSet/TMap over 64 entries comes back as its first 64 with count and truncated, and any value over 16384 characters is cut and marked truncated, so per-instance ISM data cannot swell the response (#1277). relativeTo names a scene component on the same actor (a camera, a hand) and adds relativeToComponent, each row's transform in that component's space. socketNames lists bones or sockets; every component that has sockets reports, per name, found, kind (bone|socket), componentSpace and world transforms, and relativeToComponent with relativeTo. world also takes a world object path, so a Blueprint editor preview world (/Engine/Transient.World_N, listed by editor(find_object, className=World)) is readable; with world omitted an actorPath in another world reads that world. The response names the world and worldType that answered, and each scene component also reports hiddenInGame (#240/#241/#302/#320/#370/#353/#581).", "get_component_tree"),
    get_relative_transform: specBp("read", "Compute target's transform in reference's local space (location/rotation/scale). Common dungeon/calibration workflow (#386/#387/#983).", "get_relative_transform"),
    resolve_actor:      specBp("read", "Resolve internal/runtime actor name to editor label. internalName is e.g. StaticMeshActor_141. Returns actorLabel, actorPath, className, location (#178).", "resolve_actor"),
    // lint-prose-allow: tier  RecastNavMesh's own name for its three generation tiers
    set_actor_property: specBp("mutate", "Set per-instance UPROPERTY on a level actor. 'WorldSettings' as the actorLabel targets the world settings actor. propertyName takes dotted paths like 'Foo.Bar', and a C-style FIXED ARRAY element is addressed by index: 'NavMeshResolutionParams[1].CellSize' reaches the Default tier rather than always writing element 0 (#927). value is string/number/bool/object/array; a label string resolves to an AActor* ref, and a JSON array of labels populates a TArray of actor refs (#538) (#202/#230). Blueprint instance variables are addressed by their variable name. The result reads the property back after the write: value and previousValue in export text, plus changed (#1566).", "set_actor_property"),
    read_actor_motion: specBp("read", "Snapshot motion telemetry for one or many actors: location, rotation, velocity, scale, angularVelocity (when simulating physics), grounded + distanceToGround (downward 200u trace). Defaults to the PIE world with editor fallback. Loop at your sample interval for long telemetry probes (#453).", "read_actor_motion"),
    add_hismc_instances: specBp("mutate", "Bulk-add transforms to a HISMC / ISMC component on an actor (Python add_instance crashes on UE 5.7; this is the C++ path). Each transforms entry is {location: {x,y,z}, rotation?: {pitch,yaw,roll}, scale?: {x,y,z}}; componentName defaults to the first ISMC/HISMC found (#434).", "add_hismc_instances"),
    get_instance_transforms: specBp("read", "Read every instance transform on an actor's ISMC/HISMC; componentName defaults to the first. Returns instances[{index, location, rotation, scale}] (#697).", "get_instance_transforms"),
    update_instance_transform: specBp("mutate", "Update a single ISMC/HISMC instance by index; unspecified location/rotation/scale are preserved (#697).", "update_instance_transform"),
    remove_instance: specBp("mutate", "Remove a single ISMC/HISMC instance by index (#697).", "remove_instance"),
    set_nanite_settings: specBp("mutate", "Enable/disable + force-build Nanite on a UStaticMesh asset (rebuilds render data immediately, not on next cook) (#696).", "set_nanite_settings"),
    get_nanite_info: specBp("read", "Read a UStaticMesh's Nanite state (naniteEnabled, positionPrecision, numLODs) (#696).", "get_nanite_info"),
    add_post_process_blendable: specBp("mutate", "Add a material blendable (post-process material or MID, e.g. a toon/outline pass) to a PostProcessVolume's WeightedBlendables (#666).", "add_post_process_blendable"),
    set_post_process_settings: specBp("mutate", "Write post-process settings AND enable the bOverride_<Name> flag for every key given. Inside FPostProcessSettings each value is gated by its own override bit, so writing AutoExposureMinBrightness through the generic property setter stores the number, leaves the bit off, and the engine keeps using the default while the details panel shows the value you asked for. Nothing errors. That is the trap this closes: the auto-enable IS the action. Works off the struct's reflected fields, so every setting is reachable, not just exposure, and a key that has no override bit (WeightedBlendables) says so instead of implying one was enabled. Every key is resolved BEFORE anything is written, so a typo fails the call rather than half-applying it, and each key reports previousValue, newValue, overrideWasEnabled and overrideEnabled read back from the struct. Finds the settings on the actor or on one of its components; a camera with several camera components needs componentName (or propertyName) and is refused by listing the candidates rather than by picking one. The level is left dirty and is NOT saved (#950).", "set_post_process_settings"),
    get_post_process_settings: specBp("read", "Read post-process settings with the override bit that decides whether each one applies. onlyOverridden answers 'is this volume actually overriding exposure' directly, instead of dumping the whole FPostProcessSettings as one ExportText blob to parse. Each row is name, type, value, overridden (the bOverride_<Name> bit) and hasOverrideFlag; the bits themselves are not listed as settings of their own, because a caller who writes the bit without the value has changed nothing. Also returns totalSettings and overriddenCount, so 'nothing is overridden here' is a fact rather than an empty list (#950).", "get_post_process_settings"),
    set_fixed_exposure: specBp("mutate", "Pin exposure on a post-process volume or camera in one call. Writes the same value to AutoExposureMinBrightness and AutoExposureMaxBrightness, which is how the engine disables eye adaptation, and enables both override flags so the values actually apply (#950).", "set_fixed_exposure"),
    export_actor_fbx: specBp("mutate", "Export an actor's skeletal/static mesh to FBX and write a metadata sidecar JSON (actor transform, mesh, materials, skeleton) for a downstream bridge (e.g. MetaTailor). Returns fbx + metadata paths (#637).", "export_actor_fbx"),
    spawn_skeletal_mesh_actor: specBp("mutate", "Spawn a SkeletalMeshActor for visual/deform verification. Optional per-slot COMPONENT material overrides (they write the component's OverrideMaterials, not the mesh ASSET's slots, which material(build_material) writes) and single-node animation preview (animSequence + loop). Each entry in materials[] comes back with ok, and a path that does not load or a slot index past the mesh's slot count is reported rather than silently dropped, because a silently dropped assignment reads as one that worked. To dress an actor that is already placed, or to put one material on every slot, use level(set_component_materials) (#946). Returns actorLabel + boxExtent + materialSlotCount. The animSequence is written to the component's editable AnimationData, so it persists across a level save/reload instead of only driving the runtime preview and coming back in A-pose (#790) (#679/#677).", "spawn_skeletal_mesh_actor"),
    delete_actors: specBp("mutate", "Bulk-delete actors. The filter names say exactly what they match, because two level actions taking similar-sounding filters with different semantics is how a caller ends up trusting a wrong zero (#963): labelPrefix is a CASE-SENSITIVE PREFIX over the EDITOR LABEL, labelContains a case-insensitive SUBSTRING over the label, nameContains a case-insensitive substring over the INTERNAL name, className a case-sensitive substring over the class name. get_outliner's nameFilter is looser than any of them (label OR internal name, substring), so a string that selects a set there can select a different set here. When nothing matches, the response explains it rather than returning a bare zero: zeroMatchHint reports how many actors the same string WOULD have matched under the other semantics with samples, and a World Partition map says that only loaded actors were enumerated. classPathContains is a case-insensitive substring of the generated UClass path (e.g. /SurvivalGameKitV2/), so a whole vendor folder can be selected without listing every Blueprint class, and classPathContainsAny is the same match against any of several substrings (#924). folderPath selects one World Outliner folder exactly and folderPathPrefix that folder and everything nested under it, the same folder match get_outliner and query_components use; a folder filter that matches nothing returns similarFolders (#1529). dryRun previews. Returns matched/deleted/labels/classPaths/folderPaths (#220/#924/#963).", "delete_actors"),
    delete_exact_labeled_actors_in_levels: specBp("mutate", "Delete actors by EXACT label across several map packages in one call, without leaving the maps open or dirty. Previews by default (dryRun defaults to TRUE, the opposite of delete_actors), and every level is loaded and preflighted before anything is deleted, so a bad label in the last map cannot half-commit the first. Refuses the whole request on duplicate labels, a class that does not match expectedClassPath, actors living in a streaming sublevel, WorldSettings/default brush/level blueprint, World Partition maps, a read-only .umap, or an editor that is already dirty. Saves only the maps it actually changed, then returns to the map that was open. Limits: 16 levels, 256 labels per level. onMissing=ignore makes a replay idempotent.", "delete_exact_labeled_actors_in_levels"),
    list_actor_descs: specBp("read", "World Partition ONLY: list on-disk actor descriptors, including actors whose cell is not loaded and which every other actor query therefore reports as absent. Returns guid/label/class/package/folderPath/bounds/runtimeGrid/dataLayers plus a loaded flag, and separate loadedMatches/unloadedMatches counts so 'not streamed in' is distinguishable from 'does not exist'. packages[] looks actors up by their external actor package (full path or the XX/YY/NAME tail, as a changelist lists them) and reports the ones no descriptor holds as missingPackages. Needs UE 5.5 or newer (#746).", "list_actor_descs"),
    load_actor_descs: specBp("mutate", "World Partition ONLY: pin matched actors so they become resident and the normal actor actions can reach them, or unpin to release. Pinning is used rather than transient streaming because a transient load is dropped again by the streaming system mid-measurement. Takes the same filters as list_actor_descs (packages[] included, with missingPackages) and refuses to act on more than maxActors (default 256) so an unfiltered call cannot pin a whole map by accident. Reports residentAfter, read back from the world rather than assumed. Unpinning releases pins and nothing else: an actor an editor loaded region or location volume holds stays resident, and list_loaded_regions / unload_loaded_regions release those. Needs UE 5.5 or newer (#746).", "load_actor_descs"),
    list_loaded_regions: specBp("read", "World Partition ONLY: list the editor loader adapters that keep actors resident, which load_actor_descs(unpin) cannot release because they are not pins: user loaded regions (the World Partition editor's Load Region from Selection, and the regions the editor restores when a map is reopened), location volumes, and any other loader the engine tracks. Each row has an id that unload_loaded_regions accepts, its kind (userRegion, locationVolume, actor or other), label, bounds, loaded, and actorCount / residentActors / dirtyActorPackages measured over those bounds (the adapter keeps its own reference set private, so the count is the spatially loaded descriptors that meet the box). Unloaded sources are hidden unless includeUnloaded=true. Paged. Needs UE 5.5 or newer.", "list_loaded_regions"),
    unload_loaded_regions: specBp("mutate", "World Partition ONLY: unload editor loaded regions and location volumes by id (from list_loaded_regions) and/or by a bounds box, the same as Unload Region in the World Partition editor, which is the only way to make actors a loaded region holds non-resident. Refuses the whole request, unloading nothing, when a region holds actors whose packages are dirty (their unsaved edits would be discarded) unless force=true; refuses more than maxRegions (default 8) so a wide box cannot unload everything; dryRun previews. residentAfter is read back from the world over the unloaded footprint, with residentPinnedAfter and a note when something else (a pin, an overlapping region) still holds actors. Needs UE 5.5 or newer.", "unload_loaded_regions"),
    load_region: specBp("mutate", "World Partition ONLY: load a box as a user loaded region, the same as Load Region from Selection in the World Partition editor, and return its id for unload_loaded_regions. Refuses a box holding more than maxActors (default 256) actors; a loaded region over the same box is reported as existed. Its rollback is unload_loaded_regions for that id. Needs UE 5.5 or newer.", "load_region"),
    get_world_partition_settings: specBp("read", "World Partition ONLY: the streaming knobs on the open map, plus the runtime cell transformer stack. Returns the world partition and runtime hash classes, whether streaming is enabled, the default HLOD layer, and grids[] with each grid's name, CellSize, LoadingRange and a dotted path rooted at the world partition. Grids are found by REFLECTION rather than against a fixed class, so this answers for the RuntimeHashSet layout and the older spatial hash alike. cellTransformers[] lists each stack entry with its class, its instancePath and the current values of the instanced transformer object's editable properties, which no read exposed (#985).", "get_world_partition_settings"),
    set_world_partition_settings: specBp("mutate", "World Partition ONLY: write the streaming knobs. cellSize and loadingRange are the shorthand for the primary tuning pair and pick the map's only grid automatically, or name one with grid (its name) or gridPath (the dotted path from get_world_partition_settings). settings takes any dotted path rooted at the world partition, which is how the INSTANCED runtime cell transformer object is configured ('RuntimeCellsTransformerStack[0].Instance.SomeProperty') - that object is read-only through Python and was previously set by hand in the editor UI. Every path is resolved BEFORE anything is written, so a bad path fails the call rather than leaving the map streaming on a mixture nobody asked for, and each write reports previousValue and the value read back. Streaming settings only apply to cells generated after the change, so rebuild the streaming data before measuring. The map package is left dirty and is NOT saved (#985).", "set_world_partition_settings"),
    add_runtime_cell_transformer: specBp("mutate", "World Partition ONLY: append a WorldPartitionRuntimeCellTransformer to RuntimeCellsTransformerStack and configure its instanced object in the same call. Adding the entry without being able to write the instance would leave the manual editor step exactly where it was, so the instance is created here and properties are applied to it. skipIfPresent (default true) makes a rerun a no-op that reports the existing index instead of stacking duplicates. position inserts at an index rather than appending, because the stack is ordered (#985).", "add_runtime_cell_transformer"),
    set_world_partition_streaming: specBp("mutate", "World Partition ONLY: turn streaming on or off for the open map (UWorldPartitionSubsystem::SetStreamingEnabled on UE 5.9, UWorldPartition::SetEnableStreaming before it). With streaming off every actor is always loaded. An unchanged state is reported as unchanged; the rollback sets the previous state (#1828).", "set_world_partition_streaming"),
    set_runtime_hash_class: specBp("mutate", "World Partition ONLY, UE 5.9: convert the open map's runtime hash to another class (WorldPartitionRuntimeHashSet, WorldPartitionRuntimeSpatialHash), keeping what the conversion supports. Refusals quote the engine's reason (#1828).", "set_runtime_hash_class"),
    list_runtime_partitions: specBp("read", "World Partition ONLY, UE 5.9: the runtime hash set's partitions in declaration order, each with its class and HLOD setup names (#1828).", "list_runtime_partitions"),
    get_runtime_partition: specBp("read", "World Partition ONLY, UE 5.9: one runtime partition's class and editable properties (cell size, loading range...), or with setupName the partition of one of its HLOD setups; hasPartition=false for a setup without one (#1828).", "get_runtime_partition"),
    add_runtime_partition: specBp("mutate", "World Partition ONLY, UE 5.9: add a runtime partition to the runtime hash set (default class RuntimePartitionLHGrid), with default values and no HLOD setups. A name already there is reported as existed; the rollback removes the new partition (#1828).", "add_runtime_partition"),
    remove_runtime_partition: specBp("mutate", "World Partition ONLY, UE 5.9: remove a runtime partition; the last one cannot be removed. Actors still assigned to it stream with the first partition until reassigned. An absent name is reported as alreadyRemoved (#1828).", "remove_runtime_partition"),
    rename_runtime_partition: specBp("mutate", "World Partition ONLY, UE 5.9: rename a runtime partition; HLODs must be rebuilt afterwards. The rollback renames it back (#1828).", "rename_runtime_partition"),
    set_runtime_partition_properties: specBp("mutate", "World Partition ONLY, UE 5.9: write editable properties of a runtime partition (or, with setupName, of one of its HLOD setup partitions), the way the subsystem documents changing their settings. Every name is checked before anything is written; returns previous and readBack, and the rollback writes the previous values (#1828).", "set_runtime_partition_properties"),
    list_hlod_setups: specBp("read", "World Partition ONLY, UE 5.9: a runtime partition's HLOD setups in hierarchy order, each with its partition class and HLOD layers. The non-spatially loaded setup, when present, is last and named None (#1828).", "list_hlod_setups"),
    add_hlod_setup: specBp("mutate", "World Partition ONLY, UE 5.9: add a spatially loaded HLOD setup without layers after the partition's existing ones; its partition is derived from the previous level. The rollback removes it (#1828).", "add_hlod_setup"),
    remove_hlod_setup: specBp("mutate", "World Partition ONLY, UE 5.9: remove a spatially loaded HLOD setup, leaving its layers unassigned (listed in unassignedHlodLayers). The None setup cannot be removed (#1828).", "remove_hlod_setup"),
    set_hlod_setup_layers: specBp("mutate", "World Partition ONLY, UE 5.9: assign HLODLayer assets to an HLOD setup, removing them from the partition's other setups; an empty array leaves it without layers. The rollback restores the setup's previous layers (#1828).", "set_hlod_setup_layers"),
    build_hlod_actors: specBp("mutate", "World Partition ONLY: build loaded HLOD actors in place, as their details panel's Build HLOD button does (UWorldPartitionSubsystem::BuildHLODActors on UE 5.9, AWorldPartitionHLOD::BuildHLOD before it). Omit actorLabels for every loaded HLOD actor; up to date actors are skipped unless force. Does not save (#1828).", "build_hlod_actors"),
    build_world_partition_hlods: specBp("mutate", "World Partition ONLY, UE 5.9: set up and build the open map's HLODs in an external process, as the Build HLODs menu does (UWorldPartitionSubsystem::BuildHLODs). Every modified package must be saved first. The map is unloaded and reopened, so earlier actor references go stale. hlodLayer builds only that layer's HLODs (#1828).", "build_world_partition_hlods"),
    delete_world_partition_hlods: specBp("mutate", "World Partition ONLY, UE 5.9: delete every HLOD of the open map in an external process (UWorldPartitionSubsystem::DeleteHLODs). Every modified package must be saved first; the map is unloaded and reopened (#1828).", "delete_world_partition_hlods"),
    get_hlod_stats: specBp("read", "World Partition ONLY, UE 5.9: build statistics of every HLOD actor from its saved descriptor, without loading it: name, hlodLayer, spatiallyLoaded, dataLayers and stats (InputActorCount, MeshTriangleCount, MemoryDiskSizeBytes, BuildTimeTotalMilliseconds...). HLOD actors created since the last save are not listed yet (#1828).", "get_hlod_stats"),
    get_world_partition_minimap: specBp("read", "World Partition ONLY: the open map's minimap actor and its settings, with the world bounds a build would capture and the texture resolution it would produce (UE 5.9). exists=false when the map has no minimap actor (#1828).", "get_world_partition_minimap"),
    create_world_partition_minimap: specBp("mutate", "World Partition ONLY: spawn the minimap actor in the persistent level when the map has none (UWorldPartitionSubsystem::GetMiniMap with bCreateIfMissing). An existing actor is reported as existed; the rollback deletes a new one (#1828).", "create_world_partition_minimap"),
    build_world_partition_minimap: specBp("mutate", "World Partition ONLY, UE 5.9: build and save the open map's minimap in an external process, as the Build World Partition Editor Minimap menu does, without its prompts. Every modified package must be saved first; the map is unloaded and reopened (#1828).", "build_world_partition_minimap"),
    check_world_partition_errors: specBp("read", "World Partition ONLY, UE 5.9: the map's World Partition problems, as Map Check's World Partition validation and the Scene Outliner's Repair Errors see them: errorType, severity, message and the actor, referenced actor or object each names, with errors and warnings counts (#1828).", "check_world_partition_errors"),
    repair_world_partition_errors: specBp("mutate", "World Partition ONLY, UE 5.9: repair what check_world_partition_errors reports as NotUsingExternalActors, WorldDataLayersNotSaved and InvalidActorFile, as the Scene Outliner's Repair Errors button does. Saves, deletes invalid actor files and clears the undo history when actors move; not undoable. Reports repairableBefore and repairableAfter (#1828).", "repair_world_partition_errors"),
    replace_actors_with_class: specBp("mutate", "Replace actors with new instances of an actor class, as the editor's Replace Selected Actors With command does (UEditorActorSubsystem::ReplaceActorsWithClass on UE 5.9, the same factory path before it). The class needs an actor factory that works without an asset (lights, empty actors, volumes); asset-backed classes go through replace_actors_with_asset. One undo transaction; returns newActors (#1828).", "replace_actors_with_class"),
    replace_actors_with_asset: specBp("mutate", "Replace actors with new actors created from an asset (static mesh, Blueprint, particle system), as the editor's Replace Selected Actors With command does (UEditorActorSubsystem::ReplaceActorsWithAsset on UE 5.9). copySourceProperties (default true) copies a replaced actor's values when the asset is a Blueprint sharing its native parent. One undo transaction; returns newActors (#1828).", "replace_actors_with_asset"),
    rebuild_brush: specBp("mutate", "UE 5.9: rebuild a brush or volume's geometry from a brush builder without changing its transform, pivot or visibility (UEditorActorSubsystem::RebuildBrush). builderClass picks a builder (CubeBuilder, CylinderBuilder...), default the brush's own; builderProperties sets its parameters, such as {X, Y, Z} for a cube. The rollback rebuilds with the previous builder and values (#1828).", "rebuild_brush"),
    set_actor_hlod_layer: specBp("mutate", "Assign (or clear) the per-actor HLODLayer override across every actor a selector picks. Assigning one across 295 InstancedFoliageActors was a Python loop. Goes through the engine's own AActor::SetHLODLayer rather than writing the private property directly, so the result behaves like an edit made in the details panel. hlodLayer=null clears the override. An actor already carrying the requested layer is reported as unchanged rather than counted as an update, so a rerun is readable. Optionally sets bEnableAutoLODGeneration in the same pass, since the layer only matters when the actor is allowed to build HLODs at all. On a World Partition map this dirties one package per actor and does NOT save (#985).", "set_actor_hlod_layer"),
    set_actor_folder_path: specBp("mutate", "Assign World Outliner folder paths in bulk. Filter with actorLabels (exact), labelPrefix, className or tag; pass an empty folderPath to move actors back to the root. Runs in one transaction so the whole move is a single undo, reads each write back (verified), and reports missingLabels for names that matched no actor. Editor-only organisation: the level is left dirty and is NOT saved (#767).", "set_actor_folder_path"),
    create_outliner_folder: specBp("mutate", "Create World Outliner folders that hold no actors yet, such as a layout to move actors into later. Pass folderPath, folderPaths, or both; nested paths like Props/Lights are fine. Each path reports created, existed or failed (invalid_path, create_failed), so a replay is readable. Its rollback is delete_outliner_folder over the folders it created (#1529).", "create_outliner_folder"),
    delete_outliner_folder: specBp("mutate", "Remove EMPTY World Outliner folders, together with the empty folders nested under them. A folder outlives its actors: emptying one with delete_actors(folderPath|folderPathPrefix) leaves the folder behind, and this is the call that clears it. A folder that still holds an actor anywhere in its subtree is refused as not_empty with the actor count and sample labels, never emptied for you. Each path reports deleted, would_delete (dryRun), absent or failed; deletedFolders lists every folder removed, and the rollback recreates them with create_outliner_folder. On a World Partition map only loaded actors are checked (#1529).", "delete_outliner_folder"),
    add_actor_tag: specBp("mutate", "Append a tag to an actor's Tags array (#219).", "add_actor_tag"),
    remove_actor_tag: specBp("mutate", "Remove a tag from an actor's Tags array (#219).", "remove_actor_tag"),
    set_actor_tags: specBp("mutate", "Replace an actor's Tags array (#219).", "set_actor_tags"),
    list_actor_tags: specBp("read", "List an actor's Tags, in the order they are authored on the actor (#219/#983).", "list_actor_tags"),
    rename_actor_object: specBp("mutate", "Rename a placed actor's OBJECT NAME (its FName, the last segment of actorPath), keeping its editor label; set_actor_label and the outliner rename change only the label. Every target is tested first and a name already held in the level is refused, because UObject::Rename onto a taken name is a fatal engine error. A batch is all or nothing: one bad entry renames nothing. newName omitted generates a unique name from the class. renames:[{actorPath|actorLabel, newName?}] renames several in ONE undo transaction. Refuses WorldSettings, the level script actor, the default brush, transient actors and actors in their own external package (World Partition, one file per actor). Returns oldName/newName/oldPath/newPath per actor and dirtiedPackages; the map is NOT saved and no redirector is created, so soft references that stored the old path do not follow. dryRun previews (#1574).", "rename_actor_object"),
    attach_actor: specBp("mutate", "Attach actor as child (#205).", "attach_actor"),
    detach_actor: specBp("mutate", "Detach actor from parent (#205/#983).", "detach_actor"),
    attach_component: specBp("mutate", "Attach an actor root or exact named child SceneComponent to an actor root or exact named parent SceneComponent. A non-root child changes only component hierarchy, not actor parentage. An already-matching attachment is a no-op and does not reapply transform rules. relativeLocation/relativeRotation set a corrective offset in the parent component or socket frame after the attach (or on an existing matching attachment), so a tool-in-hand calibration onto a skeletal socket is one call; the result reports the relative transform read back (#1250). Returns verified resolved component and socket details; native attachment failure is an error.", "attach_component"),
    detach_component: specBp("mutate", "Detach an actor root or exact named child SceneComponent while preserving world transform. Omitted childComponentName selects the actor root. An already-detached component is a verified no-op. Returns previous parent component/socket details plus alreadyDetached and detachmentChanged.", "detach_component"),
    set_actor_mobility: specBp("mutate", "Set actor root component Mobility (#205).", "set_actor_mobility"),
    get_current_edit_level: specBp("read", "Read the active edit-target sub-level (#204).", "get_current_edit_level"),
    set_current_edit_level: specBp("mutate", "Set the active edit-target sub-level so subsequent spawns land in it (#204).", "set_current_edit_level"),
    list_streaming_sublevels: specBp("read", "List streaming sub-levels with transform + initially-loaded/visible flags (#206).", "list_streaming_sublevels"),
    add_streaming_sublevel: specBp("mutate", "Add a streaming sub-level (#206).", "add_streaming_sublevel"),
    remove_streaming_sublevel: specBp("mutate", "Remove a streaming sub-level (#206).", "remove_streaming_sublevel"),
    set_streaming_sublevel_properties: specBp("mutate", "Update sub-level transform/visibility flags (#206).", "set_streaming_sublevel_properties"),
    spawn_grid: specBp("mutate", "Batch-spawn StaticMeshActors on a grid (#203).", "spawn_grid"),
    batch_translate: specBp("mutate", "Translate a set of actors by an offset (#203/#983).", "batch_translate"),
    place_actors_batch: specBp("mutate", "Bulk-spawn StaticMeshActors with per-instance mesh + transform. Mesh loads cached per path. Each entry may carry tags[] and a parentLabel; attaches run after every spawn with the world transform kept, so a parent may come later in the same batch, and each is reported in attachments[] with its refusal reason when it fails. Returns spawned/failedMesh/failedSpawn counts + labels, plus attached/failedAttach when any entry names a parent (#264, #1263).", "place_actors_batch"),
    batch_set_properties: {
      ...specBp("mutate", "Set the same properties on every actor an editor-side SELECTOR picks. batch_translate needs an explicit label list, which for auto-numbered labels is a payload you have to generate first; this takes tag / classFilter / labelPrefix / labelContains / folderPath instead, so '190 SpotLights tagged LichtTest' is one call. Property writes delegate to set_actor_property, so dotted paths, actor-label object references and TArray-of-actor-labels all behave identically to the single-actor action. The whole batch is ONE undo transaction. dryRun resolves every property against every matched actor's class and reports currentValue without writing. The level is left dirty and is NOT saved. Pass at least one selector: actorLabels, labelPrefix, labelContains, tag, classFilter, folderPath or folderPathPrefix (#984).", "batch_set_actor_properties"),
      timeoutMs: 300_000,
    },
    bulk_set_component_property: {
      ...specBp("mutate", "Set one property on the SAME NAMED COMPONENT across every actor a selector picks (the real case: NavModifierComponent.AreaClass on dozens of placed StaticMeshActors). Delegates to set_component_property per actor, so value semantics match exactly, including JSON null to clear an object reference. An actor that has no component of that name is reported as no_such_component rather than counted as a failure or silently skipped. One undo transaction. The level is left dirty and is NOT saved (#941).", "bulk_set_component_property"),
      timeoutMs: 300_000,
    },
    remove_components_by_class: {
      ...specBp("mutate", "Remove every instance component of a class across the actors a selector picks. remove_component takes one name at a time, which cannot reach 230 orphaned SplineMeshComponents whose names are auto-generated (SplineMeshComponent_0, _1, ...). dryRun DEFAULTS TO TRUE here, unlike delete_actors: this deletes components you cannot enumerate by name, so you see the list first. Only INSTANCE components are removed; a native or SCS component belongs to the class and is reported under skippedNonInstanceComponents rather than destroyed, because destroying it would come back on the next construction rerun. Omitting every actor selector means every loaded actor, which is a legitimate request and the reason for the dryRun default. One undo transaction. Pass componentClass and at least one selector (#907).", "remove_components_by_class"),
      timeoutMs: 300_000,
    },
    spawn_actors_batch: {
      ...specBp("mutate", "Bulk-spawn actors of ANY class with per-instance properties, from explicit transforms or from positions DERIVED in the editor. place_actors_batch is StaticMeshActor only and spawn_light takes one position. Exactly one source: instances[]; fromComponents, which places one actor per matched component at boundsOrigin + boxExtent*extentFraction + offset; or alongSpline, which scatters by distance. fromComponents defaults to space='local' on purpose: a component's WORLD bounds are axis-aligned, so 'the top of the mesh' computed from them is not on a rotated lamp post, while local bounds carry the component's own orientation. That is what makes 'a SpotLight at 72 percent of each of 190 lamp posts' one call instead of 190 bounds reads and 190 spawns. properties applies to every spawn and per-instance properties win. dryRun returns every computed transform without spawning. maxSpawn (default 500) refuses a plan bigger than you meant. The level is left dirty and is NOT saved (#987).", "spawn_actors_batch"),
      timeoutMs: 300_000,
    },
    get_skinned_vertices: specBp("read", "Read a placed skinned mesh component's vertices as posed: where they are drawn now, in the editor world or PIE (world, pieInstance). A leader-pose follower (gloves, clothing, heads driven by another component's pose) reads through its leader's pose, as it is drawn. Positions are skinned on the CPU from the render LOD the component draws (lodIndex picks another), with active morph targets applied; cloth simulation and mesh deformers are not included. space picks component (default) or world for positions, box and nearPoint. Select with boneNames (summed render weight on those bones, includeChildBones, minWeight), box {min, max}, nearPoint with radius, any combination, or none for every vertex. include picks positions, weights and triangles (default positions and weights). Each vertex returns vertexIndex (a render vertex index of that LOD, not a source vertex ID), position, influences [{boneName, boneIndex, weight}] and, with boneNames, selectedWeight; triangles lists each fully selected triangle once across pages with triangleIndex, vertexIndices and sectionIndex. Pages with startIndex and limit (default 2000, at most 20000) and returns hasMore and nextStartIndex; dumpToFile writes the whole selection to outputPath (default under Saved/UE_MCP/SkinnedVertices) and returns only the summary. Also returns lodIndex, drawnLodIndex, componentTransform, leaderPoseComponent for a follower, morphTargets applied, vertexCount, selectedVertexCount and selectedBounds. For source vertices in the bind pose use asset(read_skeletal_mesh_vertices). Read-only.", "get_skinned_vertices"),
    set_component_skeletal_mesh: specBp("mutate", "Swap the mesh on a skinned mesh component of an actor that is already placed, through SetSkinnedAssetAndUpdate. Writing SkeletalMeshAsset or SkinnedAsset as a raw property leaves the pose buffers sized for the old skeleton and crashes the editor on the next pose evaluation, so set_property, set_actor_property and set_component_property route those names through the same setter. Returns previousValue, value, materialSlotCount and materialSlotNames (slot layouts differ per mesh). One undo transaction; the level is dirtied and NOT saved (#1099).", "set_component_skeletal_mesh"),
    set_component_materials: {
      ...specBp("mutate", "Set per-slot COMPONENT material overrides on placed actors. This is the other half of material assignment and the half that had no action: material(build_material) and asset(set_property) write the mesh ASSET's slots, while a placed actor usually needs the instance override the details panel edits (OverrideMaterials). set_actor_material does one slot on whichever primitive component it finds first, so dressing a placed skeletal mesh meant a Python loop over get_num_materials(). Exactly one of: materials[] (index = slot; a null or empty entry clears just that slot's override), material (one path applied to EVERY slot), clearOverrides=true (drop every override so the asset's own slots show through). Every slot comes back with its previous and new path AND whether each is a componentOverride or the meshDefault, read back rather than echoed. Every material path is resolved before anything is written, so a bad path fails the call instead of half-applying it. Works on any UMeshComponent (static or skeletal). One undo transaction; the LEVEL is dirtied and NOT saved, the mesh asset is untouched (#946).", "set_component_materials"),
      timeoutMs: 300_000,
    },
    spawn_transient_actor: specBp("mutate", "Spawn an actor for VERIFICATION that cannot be saved into the map. Checking anything that only exists on a live actor needs a subject, and spawning a normal one and forgetting to delete it is how a SceneCapture2D ended up committed to source control. So this actor is transient by construction: RF_Transient (the package serializer skips it), bTemporaryEditorActor (an editor preview actor, kept out of the level's persistent actor list), no external actor package on a World Partition map, and its label is set with bMarkDirty=false because SetActorLabel dirties the map by default. It carries a UEMCP_TransientVerification tag so it can be listed and so destroy refuses anything it did not create, and the response reports dirtiedPackages rather than promising nothing was dirtied. initialize controls how far towards a running state it is taken, because the EDITOR WORLD HAS NOT BEGUN PLAY and a spawned actor therefore gets neither InitializeComponent nor BeginPlay: 'none' spawns only, 'construction' (default) reruns construction scripts, 'beginPlay' also registers components and dispatches the begin-play cycle on this actor, which is what a component doing its setup in BeginPlay (a GAS ability system component's attribute-set scan, for one) needs before it can be read. 'beginPlay' also runs InitializeComponent on registered components. Each returned component reports registered, wantsInitializeComponent, initialized (InitializeComponent ran or is not wanted) and hasBegunPlay, read from the component, and while BeginPlay has not run the response carries hasBegunPlay=false, componentsNotBegunPlay and a beginPlayWarning, because a function invoked on such a component can succeed and change nothing (#1480). Destroy it with destroy_transient_actor. properties (propertyName -> value) are written through set_actor_property before construction and BeginPlay, so gameplay tags, tag containers, structs and object references take the same forms they take there; each comes back in properties[] with ok, the value read back after initialization, or its error, and any failure fails the call (#1103) (#956). The lighting cache is invalidated after the spawn, as the editor does on placement, so a stationary light gets its preview shadow map channel and lights the scene without being moved (#1548).", "spawn_transient_actor"),
    destroy_transient_actor: specBp("mutate", "Destroy an actor created by spawn_transient_actor. It will ONLY destroy an actor carrying the UEMCP_TransientVerification tag and RF_Transient: a label or path that resolves to a real level actor is refused by name rather than deleted, because this is the cleanup call and a mistyped label at cleanup time is how real work disappears. Use delete_actor or delete_actors for a real level actor (#956).", "destroy_transient_actor"),
    list_transient_actors: specBp("read", "List the verification actors spawned by spawn_transient_actor that are still in the world, so nothing is left behind by accident. They cannot be saved into the map and do not survive a map reload, but they are live until destroyed (#956).", "list_transient_actors"),
    convert_brushes_to_static_mesh: {
      ...specBp("mutate", "Convert BSP brushes into StaticMeshActors via UEditorActorSubsystem::ConvertActors, generating the static meshes into destinationPath. Finishing a blockout pass otherwise meant doing it by hand. dryRun DEFAULTS TO TRUE, because conversion DESTROYS the source brushes and there is no way back to a builder brush once the map is saved. Every candidate the selector picked comes back with a verdict, so nothing is silently dropped: the default builder brush, brush shapes, volumes (both derive from ABrush and neither is geometry a player sees) and subtractive brushes (they carve space and have no surface, so converting one yields an empty mesh that looks like success) are all excluded unless you opt in by name. classFilter is EXACT by default here. Reports convertedFrom (recorded before the call, since the actors are gone after it), newActorLabels and newStaticMeshes (#911).", "convert_brushes_to_static_mesh"),
      timeoutMs: 600_000,
    },
    rerun_construction: {
      ...specBp("mutate", "Re-run the construction script on PLACED actor instances, so an SCS or construction-script change reaches the copies already in the level instead of only new ones. blueprint(run_construction_script) builds a TEMPORARY actor and throws it away, and Python cannot do this at all because Actor.rerun_construction_scripts() is missing from the wrapper. Requires actorLabels or className: this destroys and rebuilds every generated component on each match, so it will not run against a whole level implicitly. Reports reran, failed[], samples[], and how many matches have no user construction script (their generated components are still rebuilt, but a caller expecting a script change to land needs to know). Compares each actor's saved state before and after: changed[] actors leave their packages dirty (dirtiedPackages[]) and are NOT saved (#944); unchanged[] actors whose package was clean before are put back to clean (restoredCleanPackages[]), so a no-op rerun does not rewrite the file on the next save (#1547).", "rerun_construction_scripts"),
      timeoutMs: 300_000,
    },
    recreate_physics_state: {
      ...specBp("mutate", "Rebuild the physics and collision state on the components a selector picks, after the mesh data underneath them changed. Stale collision makes line_trace report a MISS through solid geometry, which is the worst kind of wrong answer because nothing about it looks wrong. dryRun DEFAULTS TO TRUE and is the preflight: it lists which components would be rebuilt and what their collision enabled state and profile are right now. Requires at least one bound and never refreshes a whole world implicitly. Returns per-component before/after collision state plus a post-refresh collisionSummary histogram (#915).", "recreate_physics_state"),
      timeoutMs: 300_000,
    },
    test_component_overlap: specBp("read", "Do two placed components overlap? Returns the boolean plus both sides' local bounds, world bounds and world transforms, and separation (when apart) or penetration depth (when overlapping). For a UBoxComponent it also returns boxExtentUnscaled, the authored BoxExtent the details panel shows, which no other read exposed. method=OBB (default) runs a separating-axis test on the components' oriented local bounds, so a rotated box is tested as a rotated box; method=AABB compares the axis-aligned world bounds and adds a per-axis gap. Deliberately geometric rather than a physics overlap query: a physics answer depends on collision state, and stale collision state is what makes a trace lie (see recreate_physics_state). Omitting a componentName selects that actor's root component (#914).", "test_component_overlap"),
    shape_trace: specBp("read", "Sweep a sphere, axis-aligned box or vertical capsule in the editor or PIE world. Uses line_trace channel names and selectors. Returns the first blocking hit plus bStartPenetrating; multi=true returns overlaps through the first blocker, capped at 64 with totalHits and truncated.", "shape_trace"),
    line_trace: specBp("read", "Line trace. world selects which world is traced: 'editor' (default) or 'pie' for the LIVE running PIE world, which is the only way to check geometry that exists once play has begun (#933). Traces simple collision by default, the same as a gameplay trace, so the result matches what the running game hits; pass traceComplex to trace per-triangle instead. multi=true returns hits[] in distance order, every overlap up to and including the first blocker, capped at 64 with totalHits and truncated; hit stays true only when something blocked. channel picks the collision channel, including channels this project renamed in its collision settings. The response echoes traceComplex, channel and the world that actually answered, and faceIndex is only present on a complex hit. Returns hit + actorLabel/actorClass/componentName/componentClass/location/impactPoint/normal/distance/faceIndex/boneName/physicalMaterial (#420, #807, #933). From inside a run_python_file script the same trace is unreal.MCPTraceLibrary.line_trace(start, end, world, pie_instance, channel, trace_complex) (#1283).", "line_trace"),
    bulk_line_trace: specBp("read", "Batch of line traces. Each traces[] item uses the same semantics as line_trace (start + end or direction+distance, simple collision by default, optional traceComplex/channel/ignoreActors). The top-level world applies to the WHOLE batch, so one call cannot straddle the editor and PIE worlds and present the results as comparable. Caps at 256. Returns results[] in traces[] order, one per item, each with the same fields as line_trace (or success=false + error for that item). A per-item multi=true returns that item's hits[] the way line_trace does, so a floor or ceiling height profile is one call (#933, #1564).", "bulk_line_trace"),
    actors_in_box: specBp("read", "Every actor whose bounds meet a world-space box (min, max). mode=overlap (default) keeps any actor whose bounds intersect the box, touching faces included; mode=contained keeps only actors whose bounds lie fully inside it. Bounds are computed the way get_actor_bounds computes them; an actor with no primitive component counts as its location (bounds.source=location), and onlyColliding drops it. Hidden means hidden in the queried world: editor-hidden for the editor world, hiddenInGame for world=pie; includeHidden keeps them. Each row: label, path, class, folderPath, location, rotation, scale, bounds{origin,extent,min,max,source}, contained, editorHidden, hiddenInGame. Rows are sorted by label; limit (default 200, max 2000) reports total and truncated (#1564).", "actors_in_box"),
    snap_instances_to_surface: specBp("mutate", "Project ISMC/HISMC instances down onto surface geometry, preserving each instance's rotation and scale. Dry-run by default: preflights every requested instance and reports what would move before anything does, then applies successful projections in one transaction with rollback. Filter the surfaces traced against with surfaceActorClass/surfaceActorLabels so instances do not snap onto each other. onMiss controls whether a miss aborts the batch or is skipped. Does not save packages (#905).", "snap_instances_to_surface"),
    summarize_static_mesh_usage: specBp("read", "Read-only inventory of which static meshes are actually placed in the loaded world, aggregated in one game-thread scan instead of walking every actor and component. This is the action for placement counts, and query_components is not a substitute for it: grouping there only increments, so one HISM holding 5,000 instances counts as 1, while this SUMS real ISM/HISM instances and counts distinct actors per mesh, and it sorts every aggregate before truncating so the top N is the true top N with an exact totalUniqueMeshes. Distinguishes actors, components and placements. Results are bounded; full-scan totals are preserved alongside the truncated rows. Loads nothing and saves nothing (#903).", "summarize_static_mesh_usage"),
    audit_performance: specBp("read", "Read-only scene performance audit of the loaded level, or of the box regionMin..regionMax, in one game-thread scan. Ranked, bounded lists with totals: trianglesByMesh (LOD0 triangles x placements, share of the level, Nanite flag), regions (gridSize X/Y cells by triangles and by shadowed-light overlap), instancingCandidates (one static mesh placed as at least instancingMinCount separate components, with the separate draws that costs), dynamicShadowCasters (count, movable count, costliest by triangles), lights (shadowed point/spot/rect lights by how many others their attenuation spheres touch, and stationary lights that may exceed the four stationary shadow channels), texelDensityOutliers and lightmapResolutionOutliers (outlierFactor above or below the median), naniteCandidates (static meshes at or over heavyTriangleThreshold rendering without Nanite, with blockers such as a translucent slot), and translucentOverdraw (translucent primitives that are large or stacked). Static estimates from asset and component data, not measurements; confirm with editor(analyze_trace). Never writes. dumpToFile writes every row to JSON.", "audit_level_performance"),
    snap_actor_to_floor: specBp("mutate", "Snap an actor's bounds-bottom to the first downward line-trace hit. Equivalent of the End-key shortcut, works on arbitrary geometry (not just Landscape). The actor lookup and the downward trace both run in the world named by world, so a PIE snap measures against PIE geometry (#933) (#419, #933). World Partition HLOD actors are skipped, since the editor makes them traceable but the game does not, and listed in skippedHlodActors; with only HLOD below, the call refuses until the cell is loaded. In the editor world the snap is one undo transaction and dirties the actor's package, reported as packageDirty.", "snap_actor_to_floor"),
    ...epicActions,
  },
  {
    ...epicSchema,
    // #1057: every key a spec'd handler declares, generated from its C++
    // registration. create and build_lighting dispatch to editor handlers, so
    // the keys only they read come from the editor spec.
    ...specSchema,
    ...borrowSchema(editorSpecSchema, ["templateLevel", "worldPartition", "quality"]),
  },
);
